INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 1, 'Which stage of a multi-stage build becomes the image you push?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 2, 'Look at what `CMD npm start` actually starts as PID 1, and who receives the SIGTERM from `docker stop`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 3, 'In a two-stage build, try listing the files of the final stage only: base image, then every COPY into that stage.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 'The api image was built from this Dockerfile and pushed:

```dockerfile
FROM node:24
WORKDIR /app
COPY . .
RUN npm ci
RUN npm run build
CMD npm start
```

Statement: "Deleting the TypeScript compiler in a later `RUN rm -rf node_modules/typescript` would make the pushed image smaller."', 'single_choice'::question_type, 'False. Every RUN, COPY and ADD adds a layer, and layers only ever add files. Deleting files in a later layer hides them, but the earlier layer that contains them is still pushed and pulled. To ship fewer bytes, never put the files into the final stage in the first place: build in one stage, then COPY --from only the runtime files into a fresh stage.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111') AND order_index = 1)
    RETURNING id
)
