WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 'A two-stage build:

```dockerfile
FROM node:24-slim AS build
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci
COPY src ./src
RUN npm run build && npm prune --omit=dev

FROM node:24-slim
WORKDIR /app
COPY --from=build /app/node_modules ./node_modules
COPY --from=build /app/dist ./dist
CMD ["node", "dist/server.js"]
```

Statement: "The final image contains neither `src/` nor the TypeScript compiler."', 'single_choice'::question_type, 'True. Only the last stage becomes the image. It starts from a clean node:24-slim and receives exactly two things from the build stage: node_modules after `npm prune --omit=dev` removed the devDependencies (typescript is one), and the compiled dist/. src/ never enters the final stage.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111'), 'Every deploy logs this for the api container:

```text
$ docker stop api
# ... 10 seconds later
api exited with code 137
```

The image ends with `CMD npm start`.

Statement: "The shell form of CMD is not the cause: Docker sends SIGTERM to the node process whether CMD is written in shell form or exec form."', 'single_choice'::question_type, 'False. The shell form runs `/bin/sh -c "npm start"`, so PID 1 is the shell (and npm below it), not node. The shell does not forward SIGTERM, so node never starts its graceful shutdown; after the 10 second grace period Docker sends SIGKILL, hence exit code 137. The exec form `CMD ["node", "dist/server.js"]` makes node PID 1 so it receives the signal itself.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_111') AND order_index = 3)
    RETURNING id
)
