INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121'), 1, 'When Docker decides whether a COPY step can be reused, which files does it compare: the ones on your disk, or the ones in the build context it received?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121'), 2, 'Look at where the build runs. A cache is only useful if the machine doing the build has the layers of the previous build, locally or imported from somewhere.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121'), 3, 'Picture a stage of five steps where step 2 misses: try listing which of steps 3, 4 and 5 Docker can still take from the cache, and why.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121'), 'The build stage still starts with `COPY . .`, and the repository has this .dockerignore:

```dockerfile
# Dockerfile (build stage)
FROM node:24-slim AS build
WORKDIR /app
COPY . .
RUN npm ci

# .dockerignore
node_modules
.git
.env
*.md
```

A developer fixes a typo in `README.md` (at the repository root) and builds again on the same machine.

Statement: "`COPY . .` and `RUN npm ci` are both reported as CACHED in this rebuild."', 'single_choice'::question_type, 'True. The cache key of a COPY is the content of the files it copies from the build context, and `*.md` keeps README.md out of the context altogether, so the copied files are identical and the COPY is reused; npm ci follows a cached step with the same instruction text, so it is reused too. The common misconception is that `COPY . .` always invalidates the cache: it only does when a file that reaches the context changed. The ordering is still fragile: any edit in src/ would reinstall every dependency.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121') AND order_index = 1)
    RETURNING id
)
