SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121'), 'The Dockerfile now copies package.json and package-lock.json, runs npm ci, and only then copies src/. Locally a source edit rebuilds in seconds, but every CI run looks like this:

```text
$ docker buildx build -t registry.example.com/rice-rocket/api:9f3c2e1 .   # fresh CI runner
#6 [build 3/7] COPY package.json package-lock.json ./
#6 DONE 0.1s
#7 [build 4/7] RUN npm ci
#7 DONE 92.4s
```

Statement: "The layer order is still wrong: once `COPY src ./src` is below `RUN npm ci`, npm ci is CACHED on this runner too."', 'single_choice'::question_type, 'False. The order is already right, which is why local rebuilds are fast. A fresh CI runner starts with an empty build cache, so there is no previous layer to reuse, whatever the order. The fix is to export and import the cache, for example `--cache-to type=registry,ref=...,mode=max` and `--cache-from type=registry,ref=...` (or `type=gha` on GitHub Actions); `mode=max` is needed so the layers of the build stage, not only those of the final image, are exported. The misconception is that the cache travels with the Dockerfile or the repository: it lives in the builder.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_121') AND order_index = 2)
    RETURNING id
)
