       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_131'), 2, 'Look at how `parseInt` treats a string that starts with digits and continues with letters, and compare it with `Number`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_131'), 3, 'Postgres'' official image takes `POSTGRES_PASSWORD_FILE=/run/secrets/db_password`: try working out why it needs a variable that holds a path rather than the password.');
