-- challenge chal_quiz_dkn_141 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dkn_141', (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dkn-2-1' AND is_deleted = false LIMIT 1), 'compose-api-postgres-quiz', 'Read the first compose deploy', 'Three statements about what went wrong when Rice Rocket first ran the api and Postgres under Compose on the VPS. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
