INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141'), 1, 'Each container has its own network stack. Which machine does `localhost` name from inside the api container?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141'), 2, 'Look at what `docker compose down` removes by default, and where the postgres image keeps its data when the compose file declares no volume for it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141'), 3, 'A Redis service on the same project network: the app connects to `redis:6379` by service name, and Redis has no `ports:` entry at all. What would publishing `6379:6379` add, and for whom?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141'), 'The api crash-loops on the VPS right after `docker compose up -d`:

```text
# compose.yaml (api service)
    environment:
      DATABASE_URL: postgres://rocket:rocket-dev-2024@localhost:5432/rocket

$ docker compose ps --format ''table {{.Service}}\t{{.Status}}''
SERVICE   STATUS
api       Restarting (1) 4 seconds ago
db        Up 3 minutes

$ docker compose logs --tail 1 api
api-1  | Error: connect ECONNREFUSED 127.0.0.1:5432
```

Statement: "Postgres is running, but `localhost` inside the api container is the api container itself, so nothing listens on 5432 there; the host in `DATABASE_URL` has to be the service name `db`."', 'single_choice'::question_type, 'True. Every container gets its own network namespace, so 127.0.0.1 inside the api container is the api container, not the VPS and not the db container. Compose puts all services of the project on one network where each service name resolves to its container: postgres://...@db:5432/... reaches Postgres. The common misconception is that containers on one host share localhost, as processes on a laptop do.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_141') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
