-- challenge chal_coding_dkn_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dkn_142', (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dkn-2-1' AND is_deleted = false LIMIT 1), 'compose-api-postgres-migrations', 'Fix the compose file: api, Postgres and migrations', 'The compose file from Rice Rocket''s first deploy runs three services: `db` (postgres:17), `migrate` (the api image running `node dist/migrate.js` once) and `api`. On the VPS the api crash-loops with `connect ECONNREFUSED 127.0.0.1:5432`, the database came back empty after `docker compose down`, and port 5432 answered from the internet. The editor holds the fixed file with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line with a piece so that: Postgres keeps its data in a named volume; db reports health with `pg_isready` and publishes no port; migrate starts only once db is healthy, and api only once db is healthy and migrate has finished successfully; api and migrate reach Postgres by service name; api publishes 3000 on 127.0.0.1 only (Nginx comes later); and no password or secret is written in the file. The VPS already has `./secrets/db_password.txt` and `./secrets/jwt_secret.txt`; postgres reads `POSTGRES_PASSWORD_FILE`, and the api''s config loader (lesson 3) reads `DATABASE_PASSWORD_FILE` and `JWT_SECRET_FILE`, so `DATABASE_URL` keeps the user and host but no password. Run grades the file with a Compose simulator that boots the project, runs `down` + `up`, and lists the published ports.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
