INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_142'), 1, 'For each symptom, ask which container is involved and what it sees: what does `localhost` mean inside the api, what keeps the db files when its container is removed, and who can reach a port published without an address?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_142'), 2, 'Look at the long form of `depends_on` (a map with `condition:` per dependency), the `healthcheck:` block of db, the `volumes:` entry of db plus the top-level `volumes:` key, and the top-level `secrets:` key with `file:`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_142'), 3, 'A worker service that waits for Redis and a one-shot seeder looks like: `depends_on: { redis: { condition: service_healthy }, seed: { condition: service_completed_successfully } }`, with `healthcheck: { test: ["CMD", "redis-cli", "ping"] }` on redis, `REDIS_URL: redis://redis:6379` and `ports: ["127.0.0.1:8080:8080"]` on the worker.');
