INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dkn_151', (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dkn-2-2' AND is_deleted = false LIMIT 1), 'healthchecks-restart-quiz', 'What Docker''s health status really says', 'Three statements about Rice Rocket''s api healthcheck and restart policy, read from `docker inspect`, `docker compose ps` and the logs. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
