INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151'), 1, 'What exactly does Docker run to decide `healthy`, and what does that command look at?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151'), 2, 'Look at the `Log` entries in `.State.Health` (ExitCode and Output), the healthcheck fields `timeout`, `retries` and `start_period`, and what a restart policy reacts to.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151'), 3, 'A cron job container checks a file with `test: ["CMD", "test", "-f", "/tmp/alive"]`: it reports `healthy` as long as the file exists, even when the job has not run for a day. What does that status prove about the job?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151'), 'During a Postgres outage the team checked the api container:

```text
# src/health.ts
app.get("/health", (_req, res) => res.status(200).json({ status: "ok" }));

$ docker inspect --format ''{{json .State.Health}}'' rice-rocket-api-1
{"Status":"healthy","FailingStreak":0,"Log":[{"Start":"2026-10-28T11:42:10Z","End":"2026-10-28T11:42:10Z","ExitCode":0,"Output":""}]}

$ docker compose logs --tail 2 api
api-1  | POST /orders 500 connect ECONNREFUSED 172.18.0.2:5432
api-1  | POST /orders 500 connect ECONNREFUSED 172.18.0.2:5432
```

Statement: "Because Docker reports the api container as `healthy`, the api could reach Postgres at that moment."', 'single_choice'::question_type, 'False. `healthy` only means the healthcheck command exited 0 in its last runs. That command calls /health, and this handler answers 200 without touching Postgres, so the probe proves the HTTP server is up and nothing else. The orders fail with ECONNREFUSED at the same time. The misconception is that Docker checks the application''s dependencies; it runs your command and trusts its exit code, so the handler has to check what the service needs.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151'), 'At the lunch peak the api''s health handler waited on a saturated database pool:

```text
# compose.yaml (api service)
    healthcheck:
      test: ["CMD", "node", "-e", "fetch(''http://127.0.0.1:3000/health'').then(r => process.exit(r.ok ? 0 : 1), () => process.exit(1))"]
      interval: 10s
      timeout: 3s
      retries: 3
      start_period: 20s

$ docker inspect --format ''{{json .State.Health}}'' rice-rocket-api-1
{"Status":"unhealthy","FailingStreak":3,"Log":[
  {"ExitCode":-1,"Output":"Health check exceeded timeout (3s)"},
  {"ExitCode":-1,"Output":"Health check exceeded timeout (3s)"},
  {"ExitCode":-1,"Output":"Health check exceeded timeout (3s)"}]}
```

Statement: "Docker marked the api `unhealthy` because three probes in a row ran longer than the 3 s `timeout`; probe failures in the first 20 s after the container started would not have counted toward those three."', 'single_choice'::question_type, 'True. A probe that runs longer than `timeout` is killed and counts as a failure (ExitCode -1 with "Health check exceeded timeout"). After `retries` consecutive failures the status becomes unhealthy, and FailingStreak shows 3. During `start_period`, failures do not count toward `retries`, which gives a slow boot time to come up. The misconception is that a hanging check is harmless because it never returns an error: to Docker, no answer within `timeout` is a failure.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_151') AND order_index = 2)
    RETURNING id
)
