-- challenge chal_coding_dkn_152 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dkn_152', (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'docker-nginx-ship-a-service') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dkn-2-2' AND is_deleted = false LIMIT 1), 'truthful-health-endpoint', 'Fix the health check that lies and hangs', '`checkHealth(deps, opts)` builds the response of the api''s GET /health, which Docker''s healthcheck and the deploy gate read. Two incidents trace back to it. During a Postgres outage it kept answering 200, so traffic kept coming to an api that failed every order. At the lunch peak a database ping hung for 30 s, the whole check hung with it, and the probe timed out instead of getting an answer; a queue that was slow but not needed for orders made it worse, because the queue was only checked after the database. Assemble the handler from the pieces; the buggy versions from the incident are among them. The finished handler runs both checks in parallel, gives each one `opts.timeoutMs` (use `opts.sleep(ms)`, which resolves after ms of fake time, instead of setTimeout), reports each check as `up`, `down` (rejected or threw) or `timeout`, and decides: db not up -> 503 with status `down`; db up but queue not up -> 200 with status `degraded`; both up -> 200 `ok`. The test harness gives you fake `deps.db` and `deps.queue` and controls the clock, and also reports how long the check took. The editor starts from the finished file with key blocks missing (`[ ] label` lines): fill each one by clicking a piece, or drag it onto the line on desktop. Some pieces are wrong on purpose.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
