INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 1, 'If one ping never answers, what is the longest your function may wait before it reports something, and what happens to the other check meanwhile?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 2, 'Compare the pieces that fill the same line: which `withTimeout` can ever resolve to `TIMEOUT`, which way of running the checks waits for db before it starts queue, and which status decision still answers 200 when db is down. How long does each take when db needs 700 ms and queue 800 ms?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 3, 'Checking two mirrors with a 500 ms budget each: `Promise.allSettled([a, b].map((m) => Promise.race([m.fetch(), sleep(500).then(() => "slow")])))` returns after at most 500 ms, with each result either fulfilled (a value or "slow") or rejected.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"with-timeout","label":"Give each check its time budget","code":"const withTimeout = (run) => Promise.race([\n    Promise.resolve().then(run),\n    opts.sleep(opts.timeoutMs).then(() => TIMEOUT),\n]);"},{"id":"run-in-parallel","label":"Run both checks at the same time","code":"const results = await Promise.allSettled(names.map((name) => withTimeout(() => deps[name].ping())));"},{"id":"map-results","label":"Report each check as up, down or timeout","code":"results.forEach((result, i) => {\n    checks[names[i]] = result.status === \"rejected\" ? \"down\" : result.value === TIMEOUT ? \"timeout\" : \"up\";\n});"},{"id":"decide-status","label":"Decide the status: db is critical, the queue is not","code":"if (checks.db !== \"up\") return { status: 503, body: { status: \"down\", checks } };\nreturn { status: 200, body: { status: checks.queue === \"up\" ? \"ok\" : \"degraded\", checks } };"},{"id":"decide-status-always-200","label":"Decide the status: db is critical, the queue is not","code":"return { status: 200, body: { status: checks.queue === \"up\" ? \"ok\" : \"degraded\", checks } };","distractor":true},{"id":"run-sequential","label":"Run both checks at the same time","code":"const results = [];\nfor (const name of names) {\n    try {\n        results.push({ status: \"fulfilled\", value: await deps[name].ping() });\n    } catch (err) {\n        results.push({ status: \"rejected\", reason: err });\n    }\n}","distractor":true},{"id":"with-timeout-no-race","label":"Give each check its time budget","code":"const withTimeout = (run) => Promise.resolve().then(run);","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'Both dependencies up: 200 ok, and the checks run in parallel', '{"db":{"ping":"resolve","afterMs":20},"queue":{"ping":"resolve","afterMs":30},"timeoutMs":1000}', '{"status":200,"body":{"status":"ok","checks":{"db":"up","queue":"up"}},"elapsedMs":30}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'db.ping rejects: 503 down instead of 200', '{"db":{"ping":"reject","afterMs":20},"queue":{"ping":"resolve","afterMs":30},"timeoutMs":1000}', '{"status":503,"body":{"status":"down","checks":{"db":"down","queue":"up"}},"elapsedMs":30}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'queue hangs for 30 s: 200 degraded after the 1 s budget', '{"db":{"ping":"resolve","afterMs":20},"queue":{"ping":"resolve","afterMs":30000},"timeoutMs":1000}', '{"status":200,"body":{"status":"degraded","checks":{"db":"up","queue":"timeout"}},"elapsedMs":1000}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'db hangs for 30 s: 503 with db timeout after the 1 s budget', '{"db":{"ping":"resolve","afterMs":30000},"queue":{"ping":"resolve","afterMs":20},"timeoutMs":1000}', '{"status":503,"body":{"status":"down","checks":{"db":"timeout","queue":"up"}},"elapsedMs":1000}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'queue rejects: 200 degraded, the api keeps taking orders', '{"db":{"ping":"resolve","afterMs":20},"queue":{"ping":"reject","afterMs":30},"timeoutMs":1000}', '{"status":200,"body":{"status":"degraded","checks":{"db":"up","queue":"down"}},"elapsedMs":30}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'Both slow but inside the budget: total time is the slowest check, not the sum', '{"db":{"ping":"resolve","afterMs":700},"queue":{"ping":"resolve","afterMs":800},"timeoutMs":1000}', '{"status":200,"body":{"status":"ok","checks":{"db":"up","queue":"up"}},"elapsedMs":800}', 5, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'db.ping throws synchronously: reported as down, not a crash', '{"db":{"ping":"throw"},"queue":{"ping":"resolve","afterMs":20},"timeoutMs":1000}', '{"status":503,"body":{"status":"down","checks":{"db":"down","queue":"up"}},"elapsedMs":20}', 5, false, true, 7),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'Both down: 503 down with both checks reported', '{"db":{"ping":"reject","afterMs":10},"queue":{"ping":"reject","afterMs":10},"timeoutMs":1000}', '{"status":503,"body":{"status":"down","checks":{"db":"down","queue":"down"}},"elapsedMs":10}', 5, false, true, 8),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_152'), 'The budget comes from opts.timeoutMs (250 ms here), not a constant', '{"db":{"ping":"resolve","afterMs":30000},"queue":{"ping":"resolve","afterMs":100},"timeoutMs":250}', '{"status":503,"body":{"status":"down","checks":{"db":"timeout","queue":"up"}},"elapsedMs":250}', 5, false, true, 9);
