WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_161'), 'The api serves its routes without an `/api` prefix. nginx has this location:

```nginx
location /api/ {
    proxy_pass http://api:3000/;
}
```

Statement: "A request for `/api/orders?status=new` reaches the api as `/orders?status=new`."', 'single_choice'::question_type, 'True. When proxy_pass has a URI part (here the trailing "/"), nginx replaces the part of the request URI that matched the location ("/api/") with that URI and keeps the query string. The common misconception is that the trailing slash is cosmetic: without it (`proxy_pass http://api:3000;`) the original URI is passed unchanged, so the api receives /api/orders and answers 404.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_161') AND order_index = 1)
    RETURNING id
)
