       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_171'), 2, 'Look at the levels where `add_header` appears, at the last parameter of `try_files`, and at the numbers in `rate=` and `burst=`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_171'), 3, 'Same rules on different input: with `location /img/ { add_header X-Robots-Tag noindex; }` under a server that adds `Referrer-Policy`, a 200 from /img/ carries X-Robots-Tag only; and `try_files $uri /404.html` serves /404.html for a missing file without changing the URL in the browser.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_171'), 'Security headers are set at server level, and the assets location adds a cache header:

```nginx
server {
    add_header X-Content-Type-Options nosniff;
    add_header Referrer-Policy strict-origin-when-cross-origin;

    location /assets/ {
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable";
    }
}
```

Statement: "A 200 response for `/assets/index-4f9a2c.js` carries all three headers: `X-Content-Type-Options`, `Referrer-Policy` and `Cache-Control`."', 'single_choice'::question_type, 'False. add_header directives are inherited from the outer level only if the current level has no add_header of its own. The location defines one, so its responses carry only Cache-Control and lose both security headers. The common reading is that add_header appends to the inherited list; nginx replaces the list per level. Repeat the security headers in the location (or use expires 1y there instead of add_header, so the location has no add_header and inherits the server ones).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dkn_171') AND order_index = 1)
    RETURNING id
)
