       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_182'), 3, 'The same shape for a database migration: `copy table to new`, `verify new`, (fail: `drop new`), `point app at new`, `restart app`, `check app`, (fail: `point app at old`, `restart app`, `drop new`), `wait 1h`, `drop old`. The old copy is dropped last, after every check passed.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dkn_182'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"pick-colours","label":"Name the live colour and the candidate colour","code":"const live = state.active;\nconst next = live === \"blue\" ? \"green\" : \"blue\";"},{"id":"health-gate","label":"Start the candidate and wait for its healthcheck","code":"actions.push(`start ${next} ${state.candidateImage}`, `wait healthy ${next}`);\nif (!results.healthy) {\n    actions.push(`stop ${next}`);\n    return { actions, active: live };\n}"},{"id":"config-test","label":"Write the upstream file and test it","code":"actions.push(`write upstream ${next}`, \"nginx -t\");\nif (!results.configTest) {\n    actions.push(`write upstream ${live}`, `stop ${next}`);\n    return { actions, active: live };\n}"},{"id":"reload","label":"Reload nginx onto the candidate","code":"actions.push(\"reload nginx\");\nif (!results.reload) {\n    actions.push(`write upstream ${live}`, `stop ${next}`);\n    return { actions, active: live };\n}"},{"id":"smoke-test","label":"Smoke test through nginx, switch back on failure","code":"actions.push(`smoke test ${next}`);\nif (!results.smoke) {\n    actions.push(`write upstream ${live}`, \"nginx -t\", \"reload nginx\", `stop ${next}`);\n    return { actions, active: live };\n}"},{"id":"retire-old","label":"Drain and stop the old colour","code":"actions.push(`drain ${live} ${state.drainSeconds ?? 30}s`, `stop ${live}`);\nreturn { actions, active: next };"},{"id":"config-test-no-rollback","label":"Write the upstream file and test it","code":"actions.push(`write upstream ${next}`, \"nginx -t\");\nif (!results.configTest) {\n    actions.push(`stop ${next}`);\n    return { actions, active: live };\n}","distractor":true},{"id":"smoke-test-no-reload","label":"Smoke test through nginx, switch back on failure","code":"actions.push(`smoke test ${next}`);\nif (!results.smoke) {\n    actions.push(`write upstream ${live}`, `stop ${next}`);\n    return { actions, active: live };\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
